/// <summary>
/// getCountBins' and addCountBin's request. A bin belongs to one warehouse.
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountBinRequest
{
    DataAreaId dataAreaId;
    str warehouseId;
    str userId;
    str binId;
    str locationId;
}

Method.Source:
[DataMemberAttribute('DataAreaId')]
public DataAreaId parmDataAreaId(DataAreaId _value = dataAreaId)
{
    dataAreaId = _value;
    return dataAreaId;
}

[DataMemberAttribute('WarehouseId')]
public str parmWarehouseId(str _value = warehouseId)
{
    warehouseId = _value;
    return warehouseId;
}

[DataMemberAttribute('UserId')]
public str parmUserId(str _value = userId)
{
    userId = _value;
    return userId;
}

[DataMemberAttribute('BinId')]
public str parmBinId(str _value = binId)
{
    binId = _value;
    return binId;
}

[DataMemberAttribute('LocationId')]
public str parmLocationId(str _value = locationId)
{
    locationId = _value;
    return locationId;
}
